CREATE OR REPLACE FUNCTION public.axen_coin_edge_fixture(_uid uuid,_session uuid DEFAULT NULL,_seconds double precision DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_uid AND email LIKE 'coin-test-%@example.com') THEN RAISE EXCEPTION 'temporary test accounts only'; END IF; PERFORM set_config('axen.contract_write','on',true); PERFORM set_config('app.economy_write','on',true); IF _session IS NOT NULL THEN UPDATE public.focus_sessions SET started_at=now()-make_interval(secs=>_seconds),reward_active_seconds=_seconds,reward_ping_at=now() WHERE id=_session AND user_id=_uid AND reward_lifecycle='running'; ELSE INSERT INTO public.coin_transactions(user_id,amount,reason) VALUES(_uid,50,'habit'); UPDATE public.profiles SET coins=coins+50 WHERE id=_uid; END IF; END; $$; REVOKE ALL ON FUNCTION public.axen_coin_edge_fixture(uuid,uuid,double precision) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.axen_coin_edge_fixture(uuid,uuid,double precision) TO service_role;